   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="会知道？这里可是你的意识空间，我才是那个通过神血链接进入其中的外来者。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="每一次侵蚀加深时，我就会做梦，梦到一些很清晰的记忆。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="直到最近，我甚至能很清晰地记起年代久远的事情了。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我是个孤儿，是一名船长收养了我，给我取了“赫梅克”的名字。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那首船歌……也是她教给你的吗？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克点点头，嘴角勾起一缕怀念。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说这是“太阳”的意思，是极北冰海上最亮的光，她希望我能成为保佑她航海顺利的护身符。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她从来不用小孩子的称呼叫我，也从来不让我叫她妈妈……我们彼此心照不宣。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来，航线变得不再安全，海中怪兽时常出现袭击船只，而军队对此却视而不见。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
