   [163]={next_id=164, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人类……本就是弱小的生物，相比起力量强大的虚蚀猎人，甚至是大部分的修格尔和异变体，人类简直弱不禁风，只是随手一挥可能就命丧当场。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_107.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
